import{_ as s,H as e,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"11 | SQL优化：如何发现SQL中的问题？","description":"","frontmatter":{},"headers":[{"level":2,"title":"前置知识","slug":"前置知识","link":"#前置知识","children":[{"level":3,"title":"EXPLAIN 命令","slug":"explain-命令","link":"#explain-命令","children":[]},{"level":3,"title":"选择索引列","slug":"选择索引列","link":"#选择索引列","children":[]},{"level":3,"title":"大表表定义变更","slug":"大表表定义变更","link":"#大表表定义变更","children":[]}]},{"level":2,"title":"面试准备","slug":"面试准备","link":"#面试准备","children":[]},{"level":2,"title":"基本思路","slug":"基本思路","link":"#基本思路","children":[]},{"level":2,"title":"优化案例","slug":"优化案例","link":"#优化案例","children":[{"level":3,"title":"覆盖索引","slug":"覆盖索引","link":"#覆盖索引","children":[]},{"level":3,"title":"优化 ORDER BY","slug":"优化-order-by","link":"#优化-order-by","children":[]},{"level":3,"title":"优化 COUNT","slug":"优化-count","link":"#优化-count","children":[]},{"level":3,"title":"索引提示优化","slug":"索引提示优化","link":"#索引提示优化","children":[]},{"level":3,"title":"用 WHERE 替换 HAVING","slug":"用-where-替换-having","link":"#用-where-替换-having","children":[]},{"level":3,"title":"优化分页中的偏移量","slug":"优化分页中的偏移量","link":"#优化分页中的偏移量","children":[]}]},{"level":2,"title":"面试思路总结","slug":"面试思路总结","link":"#面试思路总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"后端工程师的高阶面经/11｜SQL优化：如何发现SQL中的问题？.md","filePath":"后端工程师的高阶面经/11｜SQL优化：如何发现SQL中的问题？.md","lastUpdated":1795554391000}'),t={name:"后端工程师的高阶面经/11｜SQL优化：如何发现SQL中的问题？.md"};function p(n,i,h,E,r,o){return e(),a("div",null,[...i[0]||(i[0]=[l(`<h1 id="_11-sql优化-如何发现sql中的问题" tabindex="-1">11 | SQL优化：如何发现SQL中的问题？ <a class="header-anchor" href="#_11-sql优化-如何发现sql中的问题" aria-label="Permalink to &quot;11 | SQL优化：如何发现SQL中的问题？&quot;">​</a></h1><p>你好，我是大明。今天我们来聊一聊数据库中的 SQL 优化。</p><p>一般而言，在面试过程中，我都是鼓励你尽可能为自己打造熟练掌握性能优化技巧的人设。高并发项目经验可遇不可求，但是高性能是可以勉强追求的，性能优化就是追求高性能的方法。和我在微服务里面讲到的高可用相结合，你在写简历、自我介绍和面试过程中，可以有意识地展示自己在高可用和高性能方面的知识和积累。</p><p>而 SQL 优化是性能优化中最平易近人、最好准备的点。所以今天我们就来学习一下 SQL 优化的多种方案。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>SQL 优化可以看作是一个更大的主题“数据库优化”下的一个子议题。数据库优化主要包含以下内容：</p><ul><li><p>硬件资源优化：换更大更强的机器。</p></li><li><p>操作系统优化：调整操作系统的某些设置。</p></li><li><p>服务器 / 引擎优化：也就是针对数据库软件本体进行优化，比如说调整事务隔离级别。在MySQL 里面还可以针对不同的引擎做优化，比如说调整 InnoDB 引擎的日志刷盘时机。</p></li><li><p>SQL 优化：针对的就是 SQL 本身了。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/1.png" alt=""></a></p><p>如果站在数据库的角度，那么 SQL 优化就是为了达到两个目标。</p><ol><li><p>减少磁盘 IO，这个又可以说是尽量避免全表扫描、尽量使用索引以及尽量使用覆盖索引。</p></li><li><p>减少内存 CPU 消耗，这一部分主要是尽可能减少排序、分组、去重之类的操作。</p></li></ol><p>这部分知识你只需要有一个概念就可以，在面试的时候倒是不经常用到。SQL 优化是一个实践为主的面试主题，很少讨论这种纯理论的内容。</p><p>如果想要知道你优化后的效果，就需要掌握一个工具，就是 EXPLAIN 命令。</p><h3 id="explain-命令" tabindex="-1">EXPLAIN 命令 <a class="header-anchor" href="#explain-命令" aria-label="Permalink to &quot;EXPLAIN 命令&quot;">​</a></h3><p>应该说，每一个后端研发都应该掌握 EXPLAIN 命令。EXPALIN 命令的大概用法是 EXPLAINyour_sql，然后数据库就会返回一个执行计划。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/2.png" alt=""></a></p><p>执行计划有很多字段，我把最关键的地方列出来，你在面试的时候只需要记住这几个就可以了。</p><ol><li>type：指的是查询到所需行的方式，从好到坏依次是 system &gt; const &gt; eq_ref &gt; ref &gt;range &gt; index &gt; ALL。</li></ol><ul><li><p>system 和 const 都可以理解为数据库只会返回一行数据，所以查询时间是固定的。</p></li><li><p>eq_ref 和 ref 字面意思是根据索引的值来查找。</p></li><li><p>range：索引范围扫描。</p></li><li><p>index：索引全表扫描，也就是扫描整棵索引。</p></li><li><p>ALL：全表扫描，发起磁盘 IO 的那种全表扫描。</p></li></ul><ol start="2"><li><p>possible_keys：候选的索引。</p></li><li><p>key：实际使用的索引。</p></li><li><p>rows：扫描的行数。数据库可能扫描了很多行之后才找到你需要的数据。</p></li><li><p>filtered：查找到你所需的数据占 rows 的比例。</p></li></ol><p>在实践中，没有必要将这些东西都死记硬背下来。等你要解读 EXPLAIN 的返回结果的时候，再去搜索一下就行了。</p><p>一般优化 SQL 都是在 EXPLAIN 查看执行计划、尝试优化两个步骤之间循环往复，直到发现SQL 性能达标。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/3.png" alt=""></a></p><h3 id="选择索引列" tabindex="-1">选择索引列 <a class="header-anchor" href="#选择索引列" aria-label="Permalink to &quot;选择索引列&quot;">​</a></h3><p>设计索引的时候，列的选择非常关键，但是目前来说并没有特别统一的说法。你可以参考以下规则。</p><ul><li><p>外键，一般都会用于关联、过滤数据，所以正常来说都会为表的外键创建索引。</p></li><li><p>频繁出现在 WHERE 中的列，主要是为了避免全表扫描。</p></li><li><p>频繁出现在 ORDER BY 的列，这是为了避免数据库在查询出来结果之后再次排序。</p></li><li><p>频繁出现在关联查询的关联条件中的列。不过一般我们都不建议使用关联查询，所以几乎可以忽略这个。</p></li><li><p>区分度很高的列。比如每一行的数据都不同的列，并且在创建组合索引的时候，区分度很高的列应该尽可能放到左边。</p></li></ul><h3 id="大表表定义变更" tabindex="-1">大表表定义变更 <a class="header-anchor" href="#大表表定义变更" aria-label="Permalink to &quot;大表表定义变更&quot;">​</a></h3><p>优化 SQL 很多手段都是围绕索引来进行的。比如后面我给出的案例要么是修改已有的索引，要么是加索引。但在修改索引的时候，数据量大的表修改索引和数据量小的表修改索引，实施方案是完全不一样的。</p><p>修改索引或者说表定义变更的核心问题是数据库会加表锁，直到修改完成。</p><p>所以当你发现你的 MySQL 性能不行了，准备新加一个索引的时候，如果这个表的数据很多，那么在你执行加索引的命令的时候，整张表可能都会被锁住几分钟甚至几个小时。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/4.png" alt=""></a></p><p>可见大表表结构变更是一件很麻烦的事情，一般可以考虑的方案有 3 种。</p><ol><li><p>停机变更，就是把业务停下来，然后更新表结构。如果做得更加精细一点，那么就可以说只把和这个表有关的功能下线，但不需要将整个服务或者系统下线。</p></li><li><p>在业务低谷变更，比停机更新好一点，但是业务依旧受到了影响。而且万一你以为在低谷能完成变更，结果并没有，那么你就面临着业务在高峰期也不能用的问题。</p></li><li><p>创建新表，这是不停机又不想业务受到影响的方案。具体来说就是创建一张新表，这张新表就是你准备用的新的表定义。然后将旧表的数据迁移过去，我们在后面会专门讨论数据迁移方案。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/5.png" alt=""></a></p><h2 id="面试准备" tabindex="-1">面试准备 <a class="header-anchor" href="#面试准备" aria-label="Permalink to &quot;面试准备&quot;">​</a></h2><p>你需要准备很多个 SQL 优化的案例，这些案例可以体现你对 SQL 和数据库底层不同技术点的理解。为此你需要收集和整理好一些信息：</p><ul><li><p>你维护的业务的所有表结构定义（包含索引定义），每张表上执行最频繁的三个 SQL 是否用到了索引。</p></li><li><p>公司内部曾经或者已有的慢 SQL 是怎么发现、分析和优化的。然后要记住 SQL 优化前后的执行时间，以凸显优化的效果。</p></li><li><p>每一个 SQL 优化案例你都要考虑清楚面试官如果要深挖，那么会朝着什么方向深挖。</p></li></ul><p>整体上来说，SQL 优化的手段是非常多而且非常细碎的。但是在面试中，你不需要全部掌握。你只需要在面试前精心设计一下你在整个 SQL 优化里面的面试节奏就可以了。</p><p>当面试官问到这些问题的时候，你都可以将话题引导到 SQL 优化中。</p><ul><li><p>你是否做过性能优化？</p></li><li><p>接口的响应时间是多少？有没有优化的空间？</p></li><li><p>你是否了解索引？是否用过索引？</p></li></ul><p>还有一种比较罕见的面试方式是面试官会要求你手写 SQL。手写之后，面试官会进一步考察在特定的一些场景下，你的 SQL 是否会有问题。记住，但凡让你手写 SQL 的题目，你都要谨慎考虑 SQL 有没有改进的空间。</p><h2 id="基本思路" tabindex="-1">基本思路 <a class="header-anchor" href="#基本思路" aria-label="Permalink to &quot;基本思路&quot;">​</a></h2><p>面试 SQL 优化的最佳策略就是把它作为自己全方面优化系统性能的一个举措。你可以考虑这样说：</p><ul><li>某某系统是一个核心系统，对性能有很高的要求。为了让服务的响应时间降低到 100ms 以内，我做了很多性能优化的事情，比如 SQL 优化。</li></ul><p>如果你这个系统同时还要求高可用，那么你就将高可用和性能优化融合在一起。</p><ul><li>某某系统是一个核心系统，对可用性和性能都有很高的要求。公司对可用性的要求是希望能达到三个九，平均响应时间控制在 100ms 内。</li></ul><p>接下来面试官就会问一些具体的措施。比如说他可能会问：“你是怎么优化你的 SQL 查询的？”那么你可以这样回答。</p><ul><li><p>我们公司有 SQL 的慢查询监控，当我们发现接口响应时间比较差的时候，就会去排查 SQL的问题。我们主要是使用 EXPLAIN 命令来查看 SQL 的执行计划，看看它有没有走索引、走了什么索引、是否有内存排序、去重之类的操作。</p></li><li><p>初步判定了问题所在之后，我们尝试优化，包括改写 SQL 或者修改、创建索引。之后再次运行 SQL 看看效果。如果效果不好，就继续使用 EXPLAIN 命令，再尝试修改。如此循环往复，直到 SQL 性能达到预期。</p></li></ul><p>你可以用你实际接触过的案例补充说明一下。</p><p>如果案例中涉及到了变更表结构定义、增加索引或者修改索引，那么面试官就可能问你怎么找出合适的列来创建索引，以及在大表里面怎么变更表结构。</p><p>如果面试的内容比较基础，那么面试官还会问你 EXPLAIN 命令返回了什么数据。这部分内容前置知识都有，你需要记住。</p><p>此外，如果你了解怎么优化操作系统、怎么优化数据库本身，那么你可以把这些内容结合起来，将自己打造成数据库优化高手。</p><p>即便你真不会，也有一个取巧的办法。就是你去找你们公司的 DBA，问清楚公司的数据库和数据库所在的操作系统有没有设置过什么参数。你弄清楚每一个参数的含义，修改背后的逻辑，对面试也大有裨益。</p><h2 id="优化案例" tabindex="-1">优化案例 <a class="header-anchor" href="#优化案例" aria-label="Permalink to &quot;优化案例&quot;">​</a></h2><p>我这里给你一些具体的优化案例，这些案例和方法都是可以用在生产实践中的，如果你之前没有尝试过，建议你自己亲手实现一下，增强实感。</p><h3 id="覆盖索引" tabindex="-1">覆盖索引 <a class="header-anchor" href="#覆盖索引" aria-label="Permalink to &quot;覆盖索引&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">覆盖索引是最为常见的优化。比如说你执行最多的 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 语句是 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> A, B, C 三个</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">列，而且 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 里面也只有这三个列的条件，那么就可以考虑直接创建一个 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">​A, B, C</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>组合索引。</p><p>那么你可以这么介绍你的案例，关键词是覆盖索引。</p><ul><li><p>原来我们有一个执行非常频繁的 SQL。这个 SQL 查询全部的列，但是业务只会用到其中的三个列 A B C，而且 WHERE 条件里面主要的过滤条件也是这三个列组成的，所以我后面就在这三个列上创建了一个组合索引。</p></li><li><p>对于这个高频 SQL 来说，新的组合索引就是一个覆盖索引。所以我在创建了索引之后，将</p></li></ul><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SQL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 由 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 改成了 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A, B, C，完全避免了回表。这么一来，整个查询</span></span></code></pre></div><ul><li>的查询时间就直接降到了 1ms 以内。</li></ul><p>然后再进一步总结。</p><ul><li>正常来说，对于非常高频的 SQL，都要考虑避免回表，那么设计一个合适的覆盖索引就非常重要了。</li></ul><p>除了覆盖索引，还可以用索引来优化排序，也就是下面的优化 ORDER BY 案例。</p><h3 id="优化-order-by" tabindex="-1">优化 ORDER BY <a class="header-anchor" href="#优化-order-by" aria-label="Permalink to &quot;优化 ORDER BY&quot;">​</a></h3><p>这算是一个非常典型的案例。在很多场景中，我们查询一些数据之后，都要求对数据进行一定的排序，比如说按照更新时间来排序。那么你就可以这样说，关键词是将排序列加入索引。</p><ul><li>我在公司优化过一个 SQL，这个 SQL 非常简单，就是将某个人的数据搜索出来，然后按照</li></ul><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">数据的最后更新时间来排序。</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SQL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 大概是 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  xxx </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 123</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> update_time。</span></span></code></pre></div><ul><li>如果用户的数据比较多，那么这个语句执行的速度还是比较慢的。后来我们做了一个比较简单的优化，就是用 uid 和 update_time 创建一个新的索引。从数据库原理上说，在 uid 确认之后，索引内的 update_time 本身就是有序的，所以避免了数据库再次排序的消耗。这样一个优化之后，查询时间从秒级降到了数十毫秒。</li></ul><p>这种优化在现实中非常容易遇到。它的底层原理就是索引本身就是有序的。如果用表格来形容</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​uid, update_time&gt; 这个索引的数据组织形式，那么看起来大概是这样的。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/6.png" alt=""></a></p><p>所以在 uid 确定之后，数据库可以直接按照 update_time 在索引中的顺序来返回结果。在优化前，数据库就只能自己将对应 uid 的数据都读过来之后再次进行排序。优化后则是省了一次排序过程。</p><p>最后你也可以总结一下。</p><ul><li>在所有的排序场景中，都应该尽量利用索引来排序，这样能够有效减轻数据库的负担，加快响应速度。进一步来说，像 ORDER BY，DISTINCT 等这样的操作也可以用类似的思路。</li></ul><h3 id="优化-count" tabindex="-1">优化 COUNT <a class="header-anchor" href="#优化-count" aria-label="Permalink to &quot;优化 COUNT&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) 也算是一个很常用的语句了。很不幸的是，最常使用的 MySQL InnoDB</span></span></code></pre></div><p>引擎并没有存储数据总数。所以类似的语句在 MySQL InnoDB 引擎上执行起来特别慢。</p><p>那么优化 COUNT 的思路也比较简单。第一种方法是用估计值取代精确值，关键词是预估。</p><ul><li>我的这个场景对数据的准确性不是很高，所以我用了一个奇诡的方法，即用 EXPLAIN</li></ul><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your_sql，之后用 EXPLAIN 返回的预估行数。比如说 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xxx</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uid=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，就可以用 EXPLAIN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xxx </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 来</span></span></code></pre></div><ul><li>拿到一个预估值。</li></ul><p>后面你还可以进一步描述其他可行的优化。</p><ul><li>不过如果需要精确值，那么就可以考虑使用 Redis 之类的 NoSQL 来直接记录总数。或者直接有一个额外的表来记录总数也可以。</li></ul><p>这种优化就跟优化 SQL 本身没什么关系了，但是也可以认为是一种性能优化，或者架构层面的优化。</p><p>在这个回答里面，还有一个地方你要小心，那就是如果你用了 Redis 来维持总数，那么就会涉及数据一致性的问题。也就是说，如果插入数据库成功，但是更新 Redis 上的总数失败了，应该怎么办？</p><p>这本质上是一个分布式事务的问题。主要思路有两个：</p><ol><li><p>如果数据短时间不一致但是业务可以接受的话，那么就可以考虑异步刷新 Redis 上的总数。</p></li><li><p>使用 Canal 之类的工具监听 MySQL binlog，然后刷新 Redis 上的总数。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/7.png" alt=""></a></p><h3 id="索引提示优化" tabindex="-1">索引提示优化 <a class="header-anchor" href="#索引提示优化" aria-label="Permalink to &quot;索引提示优化&quot;">​</a></h3><p>在上一节课我讲到了 FORCE INDEX、USE INDEX 和 IGNORE INDEX 三个索引提示，当然我也强调了这个不是什么好的实践，尽量少用。</p><p>但是在实际工作中有些时候数据库的执行就很奇怪，要么不用索引，要么用了错误的索引，那么在这种情况下你就可以考虑使用这些索引提示来纠正数据库的行为。</p><ul><li>早期我们有一个表结构定义，上面有 A、B 两个索引。原本按照预期，我们是认为这个查询应该会走 A 这个索引。结果实际用 EXPLAIN 命令之后，MySQL 却使用了 B 索引。所以我使用了 FORCE INDEX 之后强制查询使用 A 索引，果然查询的响应时间降低到了毫秒级。</li></ul><p>同时还是需要强调一下，这个不是很好的实践，不到逼不得已都不要使用。</p><ul><li>类似于 FORCE INDEX 之类的索引提示，本身并不是什么好的实践，还是要谨慎使用。</li></ul><h3 id="用-where-替换-having" tabindex="-1">用 WHERE 替换 HAVING <a class="header-anchor" href="#用-where-替换-having" aria-label="Permalink to &quot;用 WHERE 替换 HAVING&quot;">​</a></h3><p>一般来说，数据库都是先根据 WHERE 条件找到候选的列，再根据 HAVING 条件进行二次过滤。</p><p>那么你应该可以意识到，如果能够将 HAVING 中部分条件提前到 WHERE 里，那么就可以提前将不符合条件的数据过滤掉了。</p><ul><li>早期我们有一个历史系统，里面有一个 SQL 是很早以前的员工写的，比较随意。他将原本可以用在 WHERE 里面的普通的相等判断写到了 HAVING 里面。后来我将这个条件挪到了WHERE 之后查询时间降低了 40%。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/8.png" alt=""></a></p><p>然后你可以总结出一般的规律。</p><ul><li>如果不是使用聚合函数来作为过滤条件，最好还是将过滤条件优先写到 WHERE 里面。</li></ul><p>在这个案例里面因为你提到了 SQL 的执行顺序，那么面试官可能会问 SQL 执行顺序的问题，你需要有一个心理准备。</p><h3 id="优化分页中的偏移量" tabindex="-1">优化分页中的偏移量 <a class="header-anchor" href="#优化分页中的偏移量" aria-label="Permalink to &quot;优化分页中的偏移量&quot;">​</a></h3><p>有一些 SQL 在不断执行中会产生极大的偏移量，比如说非常简单的文章列表分页，一页 50条数据，那么当你要拿第 101 页的数据，需要写成 LIMIT 5000, 50。5000 就是偏移量。实际执行中数据库就需要读出 5050 条数据，然后将前面的 5000 都丢掉，只保留 50 条。</p><p>因此优化思路就是使用小偏移量。</p><ul><li>在我们的系统里面，最开始有一个分页查询，那时候数据量还不大，所以一直没出什么问题。后来数据量大了之后，我们发现如果往后翻页，页码越大查询越慢。问题关键就在于我们用的 LIMIT 偏移量太大了。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>所以后来我就在原本的查询语句的 WHERE 里面加上了一个 WHERE id &gt; max_id 的条</span></span></code></pre></div><ul><li>件。这个 max_id 就是上一批的最大 ID。这样我就可以保证 LIMIT 的偏移量永远是 0。这样修改之后，查询的速度非常稳定，一直保持在毫秒级。</li></ul><p>同样可以总结一下。</p><ul><li>很多时候因为测试环境数据量太小，这种性能问题根本不会被发现。所以所有使用分页的查询都应该考虑引入类似的查询条件。</li></ul><p>这种优化手段还可以用于分库分表中的分页查询，我们后面会再次讨论。</p><h2 id="面试思路总结" tabindex="-1">面试思路总结 <a class="header-anchor" href="#面试思路总结" aria-label="Permalink to &quot;面试思路总结&quot;">​</a></h2><p>今天这节课我讲了 SQL 优化里面比较容易遇到的三个点：EXPLAIN 命令、选择索引列和大表表结构变更，并提供了覆盖索引、优化 ORDER BY、优化 COUNT、优化索引提示、用WHERE 替换 HAVING、优化分页中的偏移量六个案例。</p><p>此外还有一点你需要注意：花样繁多的东西，你并不需要全部掌握。比如说有很多 SQL 优化的手段可能我都没听过。因此在面试过程中你需要注意把控节奏，要掌握整个面试的主动权。或者说虽然看上去面试官还在频繁问你问题，但是他问的问题都是你心中有数的，所以实际上是你在暗中控制整个面试的过程。</p><p>而如果你不能控制好这种节奏，面试官就会随便问，那么问到你不知道的也毫不意外了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/11/9.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>听我说了这么多，你有没有其他优化 SQL 的案例呢？欢迎你分享出来。另外在计算行数上，SHOW TABLE STATUS 也能看到一个 TABLE_ROWS 列，代表表的行数，那么能不能用这个来优化 COUNT(*)？</p><p>欢迎你把你的答案分享在评论区，也欢迎你把这节课的内容分享给需要的朋友，我们下节课再见！</p>`,120)])])}const d=s(t,[["render",p]]);export{g as __pageData,d as default};
